-- Allow paid_promotion_meta_requested product events (affiliate paid-demand notify)
BEGIN;
ALTER TABLE public.product_events DROP CONSTRAINT product_events_event_type_check;
ALTER TABLE public.product_events ADD CONSTRAINT product_events_event_type_check CHECK ((event_type = ANY (ARRAY['content_library_asset_uploaded'::text, 'content_library_asset_updated'::text, 'affiliate_brand_content_viewed'::text, 'affiliate_brand_content_selected'::text, 'promotion_started'::text, 'paid_promotion_meta_requested'::text, 'paid_promotion_submitted'::text, 'organic_promotion_submitted'::text, 'onboarding_started'::text, 'promotion_preference_selected'::text, 'nettmark_partner_offer_activated'::text, 'first_creative_viewed'::text, 'first_creative_selected'::text, 'first_tracking_link_created'::text, 'first_promotion_ready'::text, 'onboarding_completed'::text, 'business_signup_completed'::text, 'business_dashboard_viewed'::text, 'offer_create_viewed'::text, 'offer_create_step'::text, 'offer_publish_clicked'::text, 'offer_publish_failed'::text, 'offer_published'::text, 'plan_choice_viewed'::text, 'plan_free_clicked'::text, 'plan_growth_clicked'::text, 'plan_growth_checkout_started'::text, 'plan_growth_activated'::text, 'dashboard_action_clicked'::text, 'meta_connect_clicked'::text, 'tracking_setup_clicked'::text, 'affiliate_requests_viewed'::text, 'content_review_clicked'::text])));
COMMIT;
